 inline void storep_(int index_of_process, double e,double wgt, bool lucky)
   {
     update_contribution(e,0.0,0.0,e, wgt);
     eproc_[index_of_process]+= fabs(e) * wgt;
     nproc_[index_of_process]+= wgt;
     if (lucky)
